insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$onboarding-tong-quan$g$, $g$Onboarding khách hàng — tổng quan & luật cứng$g$, $g$mobility$g$, $g$internal$g$, $g$Ba hệ thống admin.uts.network, app.xperise.com, vendor.xperise.com và 4 luật cứng khi setup khách.$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Đây là nguồn tham chiếu duy nhất cho quy trình setup tài khoản khách hàng của Team Vận hành. Chi tiết từng phần nằm ở các hướng dẫn: Merchant & tài xế (A), Doanh nghiệp & người dùng (B), Chính sách hạn mức Be (B1), Thẻ XPAY (B3), Lỗi thường gặp."},{"id":"m2","title":"Ba hệ thống","md":"| Hệ thống | Vai trò | Ai đăng nhập |\n|---|---|---|\n| `admin.uts.network` | Quản trị nội bộ: verify doanh nghiệp, cấp hạn mức, tạo merchant/vendor, contract & credit, quản lý phôi thẻ vật lý | Team Vận hành |\n| `app.xperise.com` | Cổng doanh nghiệp: đăng ký công ty, người dùng, chính sách, cost center, ví doanh nghiệp, thẻ XPAY | Corporate Owner / Admin doanh nghiệp |\n| `vendor.xperise.com` | Cổng đơn vị vận tải: nhân viên/tài xế, đề xuất thuê xe, thanh toán | Owner của merchant |\n\nNguyên tắc định hướng: thao tác **cấp quyền và cấp hạn mức** nằm ở admin; thao tác **vận hành hằng ngày** nằm ở cổng người dùng. Khi không chắc một thao tác nằm ở đâu, hỏi ngược lại \"đây là cấp quyền hay là dùng quyền đã cấp\"."},{"id":"m3","title":"Luật cứng — áp dụng cho mọi khách hàng","md":"Bốn điều này sai là phải làm lại từ đầu hoặc gây lỗi cho khách, nên nêu chủ động ngay cả khi người dùng không hỏi tới:\n\n1. **Email Corporate Owner không được trùng email của bất kỳ User nào.** Bug đã ghi nhận: email đã dùng làm Corporate Owner sẽ không thao tác được gì trên hệ thống. Nếu trùng, user đó mất quyền dùng. Kiểm tra ngay khi nhận file, trước khi khởi tạo bất cứ thứ gì.\n2. **Ghi lại mật khẩu sau khi đổi lần đầu.** Đây là mật khẩu bàn giao cho khách. Không lưu thì phải reset và xin OTP lại từ Team Tech.\n3. **Điền đủ Corporate Info trước khi nhấn Verify.** Thiếu trường sẽ gây lỗi và ảnh hưởng hồ sơ xuất hoá đơn.\n4. **Toggle Cost center ở admin là bắt buộc bật cho mọi doanh nghiệp** — kể cả khách chạy mô hình monthly limit. Đây là điều kiện kỹ thuật để mở tính năng cấp hạn mức, không phải lựa chọn mô hình vận hành. Mô hình vận hành chọn ở `app.xperise.com`."},{"id":"m4","title":"Phân biệt hai lớp con số","md":"Đây là nhầm lẫn tốn thời gian nhất khi setup, đặc biệt với thẻ XPAY, vì trong thực tế ba con số dưới đây thường bằng nhau nên nhìn tưởng là một:\n\n- **Credit chung / cost center / monthly limit** = *hạn mức chính sách*. Quy định được phép chi tối đa bao nhiêu. Không phải tiền.\n- **Ví doanh nghiệp** = *tiền thật*. Là nguồn để nạp số dư vào từng thẻ. Ví không đủ thì không gán thẻ được.\n\nKhi người dùng nói \"hạn mức\", hỏi lại họ đang nói lớp nào nếu ngữ cảnh chưa rõ."},{"id":"m5","title":"Khoảng trống đã biết","md":"Nêu rõ khi câu hỏi rơi vào vùng này thay vì suy đoán cho có:\n\n- **B2 — chính sách Trip Proposal / Hotel / Flight**: chưa có nội dung.\n- **Màn hình Print order và Import UID**: chưa có ảnh chụp màn hình, chỉ có mô tả bằng chữ.\n- **Cơ chế reset của cost center**: biết là reset theo chu kỳ được cấu hình hoặc được nạp lại lên hạn mức mới, nhưng chưa xác định rõ điều kiện nào quyết định cách nào."}]$g$::jsonb, 20, 'seed')
