insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$onboarding-merchant-tai-xe$g$, $g$Phần A — Setup tài khoản đơn vị và tài xế (merchant)$g$, $g$mobility$g$, $g$internal$g$, $g$Setup tài khoản đơn vị vận tải (merchant) và tài xế.$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Áp dụng cho đơn vị vận tải và đội ngũ tài xế trực thuộc.\n\n**Kết quả đầu ra:** doanh nghiệp được verify, merchant được khởi tạo kèm token, danh sách tài xế đã nạp vào hệ thống."},{"id":"m2","title":"A.1. Kiểm tra file đầu vào","md":"Làm ngay khi nhận file từ Team BD. Không khởi tạo khi còn hạng mục chưa đạt — sửa sau tốn hơn nhiều.\n\n| # | Hạng mục | Tiêu chí đạt |\n|---|---|---|\n| 1 | Email Corporate Owner (người uỷ quyền ký) | Không trùng email của bất kỳ User nào trong file |\n| 2 | Thông tin cơ bản của User | Đầy đủ thông tin theo biểu mẫu, đúng định dạng |\n| 3 | Hạn mức doanh nghiệp | Xác định rõ có chia hạn mức hay không. Nếu có: chia theo Monthly Limit của User / Cost center tổng / Dự án / Phòng ban |"},{"id":"m3","title":"A.2. Khởi tạo tài khoản đơn vị","md":"## Bước 1 — Đăng nhập app.xperise.com bằng email Corporate Owner\n\n`app.xperise.com` → màn hình đăng nhập\n\n- Đăng nhập bằng **email Corporate Owner**\n- Xác thực bằng mã OTP — **liên hệ anh Tài (Team Tech) để lấy OTP**\n- Hệ thống yêu cầu đặt lại mật khẩu sau khi đăng nhập\n- Nhập đầy đủ thông tin hiển thị trên màn hình\n\n**Lưu mật khẩu vừa đổi.** Đây là mật khẩu bàn giao cho khách. Mất thì phải reset và xin OTP lần nữa.\n\n## Bước 2 — Đăng ký công ty\n\n`app.xperise.com` → menu bên trái → **Đăng ký công ty**\n\n- Nhập **Tên công ty** và **Mã số thuế (MST)** đúng theo biểu mẫu đã nhận\n- Hệ thống bắn notification request về Telegram (Group Xperise Corporate Onboarding) — dùng noti này để xác nhận request đã lên hệ thống\n\n## Bước 3 — Bổ sung thông tin và Verify doanh nghiệp\n\n`admin.uts.network` → **Corporate**\n\n- Search theo tên doanh nghiệp vừa đăng ký\n- Setup **đầy đủ** Corporate Info: tên doanh nghiệp, MST, địa chỉ\n- Nhấn **Verify** — hệ thống bắn noti về Telegram xác nhận verify thành công\n\nĐiền đủ Corporate Info *trước* khi nhấn Verify; thiếu trường sẽ gây lỗi."},{"id":"m4","title":"A.3. Khởi tạo Merchant","md":"## Bước 4 — Tạo merchant\n\n`admin.uts.network` → **System → Merchant → Add merchant**\n\n- Điền thông tin theo sheet Doanh nghiệp trong file đã nhận\n- **Owner email phải trùng với email đã dùng ở Bước 1**\n- **Alias** theo quy ước `tên đơn vị - khu vực`, ví dụ `mailinh-binhduong`, `mailinh-hcm`\n- Sau khi khởi tạo, lưu lại các thông tin vào sheet quản lý nội bộ\n\n**Lưu token hiển thị ngay sau khi khởi tạo thành công — token chỉ hiện một lần.** Đóng màn hình mà chưa lưu là phải nhờ Tech cấp lại.\n\nĐịnh nghĩa chi tiết từng trường: https://docs.uts.network/docs/merchant/add-a-merchant"},{"id":"m5","title":"A.4. Khởi tạo tài khoản tài xế","md":"## Bước 5 — Nạp danh sách tài xế\n\n`vendor.xperise.com` → **Nhân viên → Thêm tài khoản nhân viên**\n\n- Đăng nhập bằng **account Owner** (lấy tại Bước 1)\n- Tải file mẫu về, đối chiếu định dạng với file danh sách tài xế đã nhận\n- Nhập danh sách từ file có sẵn — **bao gồm cả cột password đã có trong file**\n- Kiểm tra số lượng tài xế đã lên hệ thống và thông tin của các trường dữ liệu"},{"id":"m6","title":"Checklist hoàn tất Phần A","md":"- [ ] Tài khoản Corporate Owner đăng nhập được, đã đổi mật khẩu → mật khẩu đã lưu để bàn giao\n- [ ] Đăng ký công ty thành công → có noti request trên Telegram\n- [ ] Corporate Info đầy đủ và đã Verify → có noti verify trên Telegram\n- [ ] Merchant đã tạo, alias đúng quy ước → token đã lưu vào file nội bộ\n- [ ] Danh sách tài xế đã nạp đủ trên vendor.xperise.com → số lượng khớp file gốc"}]$g$::jsonb, 21, 'seed')
