insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$onboarding-doanh-nghiep-nguoi-dung$g$, $g$Phần B — Setup tài khoản khách hàng doanh nghiệp và người dùng$g$, $g$mobility$g$, $g$internal$g$, $g$Setup doanh nghiệp, verify, contract & credit, nạp danh sách người dùng.$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Áp dụng cho khách hàng doanh nghiệp sử dụng dịch vụ.\n\n**Kết quả đầu ra:** doanh nghiệp được verify, có hạn mức và thông tin hợp đồng/credit, danh sách người dùng đã nạp và phân quyền đầy đủ.\n\nBa bước đầu (kiểm tra file, đăng nhập, đăng ký công ty, verify) **giống hệt Phần A** — cùng thao tác, cùng lưu ý. Khác biệt bắt đầu từ B.3 trở đi."},{"id":"m2","title":"B.1. Kiểm tra file đầu vào","md":"| # | Hạng mục | Tiêu chí đạt |\n|---|---|---|\n| 1 | Email Corporate Owner (người uỷ quyền ký) | Không trùng email của bất kỳ User nào trong file |\n| 2 | Thông tin cơ bản của User | Đầy đủ thông tin theo biểu mẫu, đúng định dạng |\n| 3 | Hạn mức doanh nghiệp | Xác định rõ có chia hạn mức hay không. Nếu có: chia theo Monthly Limit của User / Cost center tổng / Dự án / Phòng ban |"},{"id":"m3","title":"B.2. Khởi tạo tài khoản doanh nghiệp","md":"## Bước 1 — Đăng nhập app.xperise.com bằng email Corporate Owner\n\n`app.xperise.com` → màn hình đăng nhập\n\n- Đăng nhập bằng **email Corporate Owner**\n- Xác thực bằng OTP — liên hệ anh Tài (Team Tech)\n- Đặt lại mật khẩu, nhập đầy đủ thông tin hiển thị trên màn hình\n- **Lưu mật khẩu để bàn giao cho khách**\n\n## Bước 2 — Đăng ký công ty\n\n`app.xperise.com` → menu bên trái → **Đăng ký công ty**\n\n- Nhập Tên công ty và MST theo biểu mẫu\n- Noti request bắn về Telegram\n\n## Bước 3 — Verify doanh nghiệp\n\n`admin.uts.network` → **Corporate** → search tên doanh nghiệp\n\n- Bổ sung đầy đủ Corporate Info (tên, MST, địa chỉ)\n- Nhấn **Verify** → noti xác nhận về Telegram"},{"id":"m4","title":"B.3. Cấu hình doanh nghiệp trên admin.uts.network","md":"## Bước 4 — Cấp hạn mức, hợp đồng và credit\n\n`admin.uts.network` → **Corporate** → chọn doanh nghiệp → **View detail**\n\n- Bật **Cost center** — **bắt buộc**, là điều kiện để mở tính năng cấp hạn mức\n- Setup **Contract Information** theo hợp đồng đã ký\n- Setup **Credit Information** — giá trị credit lấy đúng theo hợp đồng\n\n| Mục cấu hình | Nguồn dữ liệu | Ghi chú |\n|---|---|---|\n| Cost center (toggle) | Cấu hình hệ thống | Bắt buộc bật cho mọi doanh nghiệp |\n| Contract Information | Hợp đồng đã ký | Contract ID, contract date, monthly limit, contract file, reconciliation cycle, statement export mode |\n| Credit Information | Hợp đồng đã ký | Sai credit sẽ chặn giao dịch của khách — kiểm tra kỹ trước khi lưu |\n| Static Code Settings | Chỉ dùng cho thẻ XPAY | Hạn mức mặc định của thẻ — xem `b3-xpay-card.md` |\n\nChi tiết các trường:\n\n- **Contract Information**: Contract ID, Contract date, Monthly limit, Contract file, Reconciliation cycle (2 kỳ D15 & D30, hoặc 1 kỳ D30), Statement export mode (Hotel / Flight theo booking date)\n- **Credit Information**: Current credit limit, Max debt credit, Payment early (số ngày), Cashback (%), Payment deadline after (số ngày), Late payment rate (%)"},{"id":"m5","title":"B.4. Khởi tạo người dùng trên app.xperise.com","md":"## Bước 5 — Nạp danh sách và phân quyền\n\n`app.xperise.com` → **Người dùng (User) → Cập nhật nhân viên**\n\n- **Thêm nhân viên** (nhập tay) hoặc **upload file CSV theo mẫu** — khuyến nghị dùng CSV khi số lượng lớn\n- Kiểm tra danh sách đã lên đủ chưa, đối chiếu số lượng với file gốc\n- Kiểm tra các trường dữ liệu; xử lý dữ liệu lỗi (sai định dạng email, trùng lặp, thiếu trường)\n- Phân quyền từng người dùng: **Admin, Nhân viên, …** theo đúng file khách hàng cung cấp\n\n## Lưu ý riêng cho khách dùng Transportation (Be)\n\n- **Số điện thoại nên để trống** cho transport user để họ tự nhập khi kích hoạt. Nhập sẵn số sai sẽ gây lỗi khi user đăng ký trên app.\n- **Cost center**: nếu khách có phân bổ theo cost center thì vào tab Cost center để tạo; nếu không thì dùng Monthly limit. Chi tiết ở `b1-policy-be.md`."},{"id":"m6","title":"Checklist hoàn tất Phần B","md":"- [ ] File đầu vào đã kiểm tra 3 hạng mục bắt buộc → email owner không trùng user\n- [ ] Corporate Owner đăng nhập được, đã đổi mật khẩu → mật khẩu đã lưu để bàn giao\n- [ ] Doanh nghiệp đã Verify → có noti verify trên Telegram\n- [ ] Đã bật Cost center, điền Contract & Credit Information → credit khớp hợp đồng\n- [ ] Danh sách user đã nạp đủ và phân quyền đúng → số lượng khớp file gốc\n- [ ] Đã setup chính sách hạn mức → xem `b1-policy-be.md`"}]$g$::jsonb, 22, 'seed')
