insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$chinh-sach-han-muc-be$g$, $g$B1 — Setup chính sách cho khách hàng dùng Be (transportation)$g$, $g$mobility$g$, $g$internal$g$, $g$Cấu hình cost center / monthly limit cho khách dùng Be (transportation).$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Phần này cấu hình lớp quyền chi tiêu (spending authority): quy định mỗi nhân viên được phép chi bao nhiêu. Đây là **hạn mức chính sách, không phải tiền thật**."},{"id":"m2","title":"Nguyên tắc","md":"**Một doanh nghiệp chỉ chạy MỘT mô hình duy nhất: Monthly limit HOẶC Cost center — không dùng đồng thời cả hai.** Cấu hình chồng hai mô hình dẫn tới sai lệch khi kiểm soát chi tiêu và rất khó truy vết về sau.\n\n- **Monthly limit** — hạn mức cấp cho từng nhân viên, **reset mỗi tháng**.\n- **Cost center** — túi ngân sách dùng chung, **reset sau một chu kỳ được cấu hình, hoặc được nạp lại (re-top) lên hạn mức mới**, tuỳ cấu hình của doanh nghiệp."},{"id":"m3","title":"Điều kiện tiên quyết","md":"- Bật toggle **Cost center** tại `admin.uts.network` (Corporate → View detail). Đây là **điều kiện kỹ thuật** để mở tính năng cấp hạn mức, **áp dụng cho cả hai mô hình** — không phải là chọn mô hình cost center.\n- Doanh nghiệp đã Verify và đã có Contract / Credit Information.\n- Danh sách người dùng đã nạp đầy đủ trên `app.xperise.com`."},{"id":"m4","title":"Chọn mô hình theo yêu cầu khách hàng","md":"| Khách hàng yêu cầu | Mô hình | Nơi cấu hình |\n|---|---|---|\n| Chia ngân sách theo phòng ban / dự án / nhóm chi phí | Cost center | `app.xperise.com` → tab Cost center |\n| Cấp hạn mức riêng cho từng nhân viên, làm mới hàng tháng | Monthly limit | `app.xperise.com` → tab Users |\n| Không chia hạn mức | Xác nhận lại với BD trước khi setup | — |"},{"id":"m5","title":"Trường hợp 1 — Doanh nghiệp dùng Cost center","md":"`app.xperise.com` → tab **Cost center**\n\n- Tạo **một cost center tổng** nếu khách dùng chung một túi ngân sách cho toàn công ty\n- Hoặc tạo **nhiều cost center** tương ứng từng phòng ban / dự án theo đúng file khách hàng cung cấp\n- Đặt hạn mức cho từng cost center theo đúng con số trong file\n- Gán người dùng vào đúng cost center tương ứng\n\nKhi đã dùng Cost center thì **không set Monthly limit cho user nữa**."},{"id":"m6","title":"Trường hợp 2 — Doanh nghiệp dùng Monthly limit","md":"`app.xperise.com` → tab **Users**\n\n- Set **Monthly limit cho từng người** theo đúng con số trong file khách hàng cung cấp\n- Với user chưa được nêu hạn mức trong file: xác nhận lại với BD, **không tự đặt giá trị mặc định**\n- Kiểm tra lại toàn bộ danh sách sau khi set — đảm bảo không user nào bị bỏ sót\n\nMonthly limit reset vào đầu mỗi tháng. Nêu rõ cơ chế này khi bàn giao để khách không hiểu nhầm là hạn mức luỹ kế."},{"id":"m7","title":"Checklist hoàn tất Phần B1","md":"- [ ] Đã bật toggle Cost center trên admin.uts.network (bắt buộc)\n- [ ] Đã xác định mô hình áp dụng: Monthly limit HOẶC Cost center — không dùng đồng thời\n- [ ] Hạn mức đã set khớp với file khách hàng cung cấp (đối chiếu từng dòng)\n- [ ] Không user nào bị bỏ sót hạn mức\n- [ ] SĐT của transport user để trống\n- [ ] Đã bàn giao cơ chế reset hạn mức cho khách hàng"}]$g$::jsonb, 23, 'seed')
