insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$setup-the-xpay$g$, $g$B3 — Setup thẻ XPAY$g$, $g$mobility$g$, $g$internal$g$, $g$Vòng đời thẻ XPAY: in phôi, gắn UID, allocate, cấp ngân sách, gán và kích hoạt.$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Toàn bộ vòng đời thẻ: từ đặt in phôi thẻ tới lúc nhân viên kích hoạt và dùng được."},{"id":"m2","title":"Tổng quan 6 giai đoạn","md":"| Giai đoạn | Nơi thực hiện | Kết quả đầu ra |\n|---|---|---|\n| 1. Đặt in phôi thẻ | Team Vận hành → Team Tech → Nhà in | Thẻ vật lý đã dập số, tên, QR + danh sách Chip UID |\n| 2. Gắn chip UID | `admin.uts.network` → System → Physical card | Thẻ trong hệ thống đã có UID, sẵn sàng allocate |\n| 3. Allocate thẻ | `admin.uts.network` → Physical Cards | Thẻ thuộc về đúng doanh nghiệp |\n| 4. Cấu hình hạn mức & credit | `admin.uts.network` → Corporate → View detail | Credit chung + hạn mức mặc định của thẻ |\n| 5. Cấp ngân sách | `app.xperise.com` → Cost center + Ví doanh nghiệp | Cost center có hạn mức, ví có tiền thật |\n| 6. Gán thẻ & kích hoạt | `app.xperise.com` → Danh sách thẻ → Gán thẻ | Thẻ đã gán, có số dư, sẵn sàng dùng |\n\nThứ tự này không đảo được: chưa verify doanh nghiệp thì không allocate được thẻ; chưa nạp ví thì không gán được thẻ có số dư."},{"id":"m3","title":"Hai lớp con số — đọc trước khi làm","md":"- **Credit chung / cost center** = *hạn mức chính sách*. Quy định doanh nghiệp và từng thẻ được chi tối đa bao nhiêu. Không phải tiền.\n- **Ví doanh nghiệp** = *tiền thật*. Nguồn để nạp số dư vào từng thẻ.\n\nTrong thực tế ba con số (credit chung, hạn mức cost center, số dư ví) thường được set bằng nhau nên nhìn dễ tưởng là một. Nhầm hai lớp này là nguyên nhân của lỗi phổ biến nhất ở mục cuối file."},{"id":"m4","title":"B3.1. Chuẩn bị danh sách thẻ và đặt in","md":"## Bước 1 — Lập danh sách và lấy QR PAN token\n\nLập danh sách thẻ gồm:\n\n- **Tên công ty in trên thẻ**\n- **Tên khách hàng in trên thẻ** — nếu là **thẻ không định danh**, để là `THE CONG TY` hoặc `THE PHONG BAN`\n\nGửi danh sách cho **Team Tech** để lấy **QR PAN token** và **số thẻ**.\n\n## Bước 2 — Gửi nhà in và nhận thẻ về\n\n- Gửi nhà in để in phôi thẻ và dập số thẻ, tên, QR\n- Nhà in gửi lại thẻ kèm **mã Chip UID** của từng thẻ\n\nGiữ nguyên file danh sách gốc đã gửi Tech — đây là căn cứ đối chiếu `QR PAN token ↔ số thẻ ↔ Chip UID` ở bước import. Sai lệch giữa ba trường này khiến thẻ không hoạt động và rất khó truy vết sau khi đã phát cho khách."},{"id":"m5","title":"B3.2. Gắn chip UID","md":"## Bước 3 — Import UID\n\n`admin.uts.network` → **System → Physical card → Print order**\n\n- Chọn **Batch ID** là **đúng tên công ty in trên thẻ**\n- **Import UID → Import CSV**\n- Tải file mẫu về, nhập đúng **QR PAN token** và **UID chip**\n- **Kiểm tra khớp số lượng thẻ và thông tin giữa file và admin *trước* khi import**\n- Default chip generation: chọn **MIFARE Classic EV1 1K**\n- Default interface: **để trống**\n- Import file CSV để ghi UID"},{"id":"m6","title":"B3.3. Allocate thẻ vào doanh nghiệp","md":"## Bước 4 — Assign thẻ cho doanh nghiệp\n\n**Điều kiện tiên quyết:** doanh nghiệp đã khởi tạo và verify theo Phần B.\n\n`admin.uts.network` → **System → Physical card → tab Physical Cards**\n\n- Search đúng **Batch ID**\n- Chọn tất cả → **Allocate cards**\n- Chọn **đúng tên doanh nghiệp** → Allocate\n\n**Trường hợp nhiều doanh nghiệp trùng tên:** vào tab Corporate kiểm tra email Corporate Owner có khớp không, từ đó xác định đúng doanh nghiệp. Allocate nhầm đồng nghĩa với việc thẻ nằm trong kho của khách hàng khác."},{"id":"m7","title":"B3.4. Cấu hình hạn mức và credit trên admin","md":"## Bước 5 — Contract và credit chung\n\n`admin.uts.network` → **Corporate** → chọn doanh nghiệp → **View detail**\n\n- Bật dịch vụ **XCard** trong nhóm dịch vụ (Expense / Rental car / XCard) ở cột bên phải\n- **Contract Information → Set up contract**: Contract ID, Contract date, Monthly limit, Contract file, Reconciliation cycle (2 kỳ D15 & D30 hoặc 1 kỳ D30)\n- **Credit Information → Edit**: **Current credit limit = tổng hạn mức của tất cả các thẻ**, Max debt credit, Payment early, Cashback, Payment deadline after, Late payment rate — tất cả lấy theo hợp đồng\n\n## Bước 6 — Static Code Settings (hạn mức mặc định của thẻ)\n\n`admin.uts.network` → Corporate → View detail → **Static Code Settings → Edit**\n\n- Allow static code: chuyển sang **Active**\n- **Per-transaction limit**: hạn mức mỗi giao dịch\n- **Daily limit**: hạn mức theo ngày\n\nHạn mức set ở đây là **mặc định áp cho từng thẻ**. Khi gán thẻ trên `app.xperise.com` vẫn siết chặt thêm được cho từng thẻ, nhưng không nên vượt mức đã set ở admin."},{"id":"m8","title":"B3.5. Cấp ngân sách trên app.xperise.com","md":"## Bước 7 — Tạo cost center bằng đúng credit chung\n\n`app.xperise.com` → **Doanh nghiệp → Trung tâm chi phí → Thêm chi phí**\n\n- Tên cost center\n- **Hạn mức: bằng đúng credit chung đã set ở admin**\n- Định kỳ: Hàng tháng — Làm mới vào ngày: theo thoả thuận với khách (mặc định ngày 1)\n- Chọn Người sử dụng và Người phê duyệt → **Tạo mới**\n\n## Bước 8 — Topup ví doanh nghiệp\n\n`app.xperise.com` → **Doanh nghiệp → Ví doanh nghiệp** (hoặc tab **Ví công ty** trong Danh sách thẻ)\n\n- Nhấn **Nạp tiền** → nhập số tiền → xác nhận **Nạp**\n- Đây là **tiền thật** dùng để nạp số dư cho từng thẻ ở bước gán thẻ"},{"id":"m9","title":"B3.6. Gán thẻ và kích hoạt","md":"## Bước 9 — Gán thẻ\n\n`app.xperise.com` → **Doanh nghiệp → Thẻ (Danh sách thẻ) → Gán thẻ**\n\nHai chế độ: **Đơn lẻ** (gán từng thẻ) và **Gán hàng loạt** (chọn nhiều thẻ, áp dụng chung một cấu hình). Form gồm 4 khối:\n\n**1. Chọn thẻ & nhân viên**\n- Chọn thẻ trong kho\n- Loại người giữ thẻ: **Nhân viên** (thẻ định danh) hoặc **Thẻ bearer** (không định danh — bất kỳ ai đang giữ thẻ đều giao dịch được)\n- **Cost center: bắt buộc.** Với thẻ bearer, cost center là căn cứ duy nhất để quản lý chi tiêu.\n- Khi gán hàng loạt: dùng **\"Áp dụng 1 cấu hình cho tất cả thẻ đã chọn\"** rồi nhấn **\"Áp dụng cho N thẻ\"**\n\n**2. Số dư & nguồn tiền**\n- Số dư ban đầu: số tiền nạp vào mỗi thẻ\n- Nguồn tiền: **Ví công ty** (hoặc Không, nếu chưa nạp tiền)\n- Làm mới số dư: Ngày đầu tháng (làm mới vào ngày 1) hoặc Không làm mới (nạp thêm khi hết)\n\n**3. Hạn mức & kiểm soát**\n- Hạn mức chi tiêu: Mỗi giao dịch / Hạn mức theo ngày / Hàng tháng / Mỗi chuyến đi — để trống nếu không giới hạn\n- Xác thực chủ thẻ (CVM): Mã QR (ứng dụng), OTP qua SMS, hoặc Mã PIN\n- Kênh thanh toán: Chạm không tiếp xúc, QR in sẵn, Nhập tay\n\n**4. Kích hoạt**\n- **Nhân viên tự kích hoạt** — xác minh quyền sở hữu bằng OTP trong app (phương án hệ thống đề xuất)\n- **Quản trị viên kích hoạt toàn bộ** — thẻ kích hoạt ngay, nhân viên không cần xác minh OTP"},{"id":"m10","title":"Lỗi phổ biến nhất: ví không đủ khi gán hàng loạt","md":"**Số dư ví công ty phải ≥ Số dư ban đầu × Số thẻ được gán.**\n\nHệ thống nạp tiền cho từng thẻ ngay tại thời điểm gán. Ví không đủ thì các thẻ vượt quá số dư báo lỗi *\"Không thể nạp tiền vào thẻ. Vui lòng thử lại.\"* và chỉ một phần thẻ gán thành công — phần còn lại vẫn nằm trong kho, rất dễ bị bỏ sót vì màn hình đầy cảnh báo.\n\n*Ví dụ thực tế: ví có 3.000.000.000 đ, gán 118 thẻ × 300.000.000 đ/thẻ (cần 35,4 tỷ) → chỉ 7 thẻ gán được, 111 thẻ báo lỗi.*\n\nCách xử lý:\n- Tính tổng cần nạp trước khi gán: `Số dư ban đầu × Số thẻ`\n- Nạp ví đủ số đó rồi mới gán\n- Hoặc chia nhiều lô nhỏ, gán từng lô theo số dư ví hiện có\n- Sau khi gán, đối chiếu số thẻ \"Đang hoạt động\" và \"Thẻ còn trong kho\" để chắc chắn không thẻ nào bị bỏ sót"},{"id":"m11","title":"Checklist hoàn tất Phần B3","md":"- [ ] Danh sách thẻ đã gửi Tech, đã nhận QR PAN token và số thẻ → lưu file gốc để đối chiếu\n- [ ] Nhà in đã giao thẻ kèm danh sách Chip UID → đủ số lượng theo đơn\n- [ ] Đã import UID đúng Batch ID, chip MIFARE Classic EV1 1K → số lượng file khớp admin\n- [ ] Đã allocate thẻ vào đúng doanh nghiệp → đã verify email owner nếu trùng tên\n- [ ] Đã bật XCard, set Contract & Credit Information → credit = tổng hạn mức các thẻ\n- [ ] Đã set Static Code Settings (per-transaction, daily)\n- [ ] Đã tạo cost center bằng đúng credit chung\n- [ ] Đã topup ví doanh nghiệp đủ cho toàn bộ thẻ → số dư ban đầu × số thẻ\n- [ ] Đã gán thẻ, không thẻ nào báo lỗi nạp tiền → đối chiếu số thẻ còn trong kho\n- [ ] Đã chọn phương thức kích hoạt và bàn giao cho khách"}]$g$::jsonb, 24, 'seed')
