insert into guides (slug, title, service, audience, summary, version, owner, status, sections, sort, updated_by)
values ($g$loi-thuong-gap-onboarding$g$, $g$Lỗi và bẫy đã biết$g$, $g$mobility$g$, $g$internal$g$, $g$Triệu chứng → nguyên nhân → cách xử lý → cách phòng cho các lỗi setup đã gặp.$g$, '1.0', 'Team Vận hành', $g$phat-hanh$g$, $g$[{"id":"gioi-thieu","title":"Giới thiệu","md":"Đọc file này trước khi suy đoán nguyên nhân khi ai đó báo lỗi setup. Mỗi mục theo cấu trúc: triệu chứng → nguyên nhân → xử lý → phòng.\n\n---"},{"id":"m2","title":"1. User không thao tác được gì trên hệ thống","md":"**Triệu chứng:** một người dùng đăng nhập được nhưng bấm gì cũng không được, không dùng được chức năng nào.\n\n**Nguyên nhân:** email của người đó bị dùng trùng làm email Corporate Owner. Đây là **bug đã ghi nhận** — email Corporate Owner không thao tác được gì trên hệ thống.\n\n**Xử lý:** phải đổi email cho một trong hai vai trò. Không có cách khắc phục tại chỗ.\n\n**Phòng:** kiểm tra ngay khi nhận file đầu vào, trước khi khởi tạo bất cứ thứ gì. Đây là hạng mục số 1 trong bảng kiểm tra file của cả Phần A và Phần B.\n\n---"},{"id":"m3","title":"2. Mất mật khẩu Corporate Owner sau khi đổi","md":"**Triệu chứng:** không bàn giao được tài khoản cho khách vì không nhớ mật khẩu đã đặt.\n\n**Xử lý:** reset mật khẩu và xin OTP lại từ Team Tech (anh Tài).\n\n**Phòng:** lưu mật khẩu vào file quản lý nội bộ ngay tại thời điểm đổi, không để sau.\n\n---"},{"id":"m4","title":"3. Mất token merchant","md":"**Triệu chứng:** cần token để tích hợp nhưng không tìm thấy.\n\n**Nguyên nhân:** token chỉ hiển thị **một lần** ngay sau khi khởi tạo merchant thành công.\n\n**Xử lý:** liên hệ Team Tech.\n\n**Phòng:** lưu token vào file quản lý nội bộ trước khi đóng màn hình.\n\n---"},{"id":"m5","title":"4. Verify xong mới phát hiện thiếu thông tin doanh nghiệp","md":"**Triệu chứng:** hồ sơ doanh nghiệp thiếu trường, ảnh hưởng xuất hoá đơn.\n\n**Phòng:** điền đủ Corporate Info (tên, MST, địa chỉ) *trước* khi nhấn Verify.\n\n---"},{"id":"m6","title":"5. Transport user không đăng ký được trên app Be","md":"**Triệu chứng:** user báo lỗi khi kích hoạt trên app.\n\n**Nguyên nhân:** số điện thoại đã nhập sẵn không khớp số user thực dùng.\n\n**Phòng:** **để trống số điện thoại** cho transport user, để họ tự nhập khi kích hoạt.\n\n---"},{"id":"m7","title":"6. Kiểm soát chi tiêu sai lệch, không truy vết được","md":"**Nguyên nhân:** doanh nghiệp bị cấu hình cả Monthly limit lẫn Cost center.\n\n**Phòng:** mỗi doanh nghiệp chỉ chạy **một** mô hình. Lưu ý toggle Cost center ở admin bật cho mọi doanh nghiệp — đó là điều kiện kỹ thuật, không phải lựa chọn mô hình.\n\n---"},{"id":"m8","title":"7. Thẻ không hoạt động khi khách quẹt","md":"**Nguyên nhân:** sai lệch giữa QR PAN token, số thẻ và Chip UID ở bước import — hoặc số dòng CSV không khớp số thẻ trong batch.\n\n**Xử lý:** phải xử lý thủ công từng thẻ, rất tốn thời gian sau khi thẻ đã phát cho khách.\n\n**Phòng:** đối chiếu số lượng và thông tin giữa file và admin **trước** khi import, không import rồi mới kiểm tra. Giữ file danh sách gốc đã gửi Tech làm căn cứ đối chiếu.\n\n---"},{"id":"m9","title":"8. Thẻ nằm trong kho của khách hàng khác","md":"**Nguyên nhân:** allocate nhầm doanh nghiệp khi hệ thống có nhiều doanh nghiệp trùng tên.\n\n**Phòng:** vào tab Corporate kiểm tra email Corporate Owner có khớp không trước khi allocate.\n\n---"},{"id":"m10","title":"9. \"Không thể nạp tiền vào thẻ. Vui lòng thử lại.\"","md":"**Triệu chứng:** gán thẻ hàng loạt, màn hình bắn hàng loạt cảnh báo, chỉ một phần thẻ gán thành công.\n\n**Nguyên nhân:** số dư ví công ty < Số dư ban đầu × Số thẻ. Hệ thống nạp tiền cho từng thẻ ngay tại thời điểm gán.\n\n**Xử lý:** nạp thêm ví rồi gán tiếp phần còn lại; hoặc chia lô nhỏ theo số dư ví hiện có.\n\n**Phòng:** tính tổng `số dư ban đầu × số thẻ` trước khi gán. Sau khi gán, đối chiếu số thẻ \"Đang hoạt động\" với \"Thẻ còn trong kho\" — phần thẻ lỗi vẫn nằm trong kho và rất dễ bị bỏ sót vì màn hình đầy cảnh báo.\n\n---"},{"id":"m11","title":"10. Khách hiểu nhầm hạn mức là luỹ kế","md":"**Triệu chứng:** khách thắc mắc vì sao hạn mức \"mất\" vào đầu tháng.\n\n**Phòng:** nêu rõ cơ chế reset khi bàn giao — Monthly limit reset đầu mỗi tháng; cost center reset theo chu kỳ được cấu hình hoặc được nạp lại lên hạn mức mới."}]$g$::jsonb, 25, 'seed')
